def build_remediation_section(remediations: Dict[str, Any], only_text: bool
    =False, columns: int=get_terminal_size().columns, kwargs: Optional[Dict
    [str, Any]]=None) ->List[str]:
    if not kwargs:
        kwargs = {}

    lines = ['   REMEDIATIONS']

    if is_using_api_key():
        for pkg_name, versions in remediations.items():
            for version_spec, remediation in versions.items():
                vuln_count = remediation.get('vulnerabilities_found', 0)
                vuln_text = 'vulnerability' if vuln_count == 1 else 'vulnerabilities'

                lines.append(f'\n-> {pkg_name} version {remediation.get("version")} was found, which has {vuln_count} {vuln_text}')

                closest = remediation.get('closest_secure_version', {})
                recommended = remediation.get('recommended_version')

                if closest:
                    closest_version = closest.get('upper') or closest.get('major')
                    if closest_version:
                        lines.append(f'   The closest version with no known vulnerabilities is {closest_version}')

                other_versions = remediation.get('other_recommended_versions', [])
                if other_versions:
                    if len(other_versions) == 1:
                        lines.append(f'   We recommend updating to version {recommended} of {pkg_name}. Other version')
                        lines.append(f'   without known vulnerabilities is {other_versions[0]}')
                    else:
                        lines.append(f'   We recommend updating to version {recommended} of {pkg_name}. Other versions')
                        lines.append(f'   without known vulnerabilities are: {", ".join(other_versions)}')
                else:
                    lines.append(f'   We recommend updating to version {recommended} of {pkg_name}.')

                more_info_url = remediation.get('more_info_url', '')
                if more_info_url:
                    lines.append(f'   For more information about the {pkg_name} package and update options, visit')
                    lines.append(f'   {more_info_url}')

                lines.append('   Always check for breaking changes when updating packages.')
    else:
        rem_count = get_remediations_count(remediations)
        vuln_text = 'vulnerability' if rem_count == 1 else 'vulnerabilities'
        pkg_count = len(remediations)
        pkg_text = 'package' if pkg_count == 1 else 'packages'

        lines.append(f'\n  {rem_count} {vuln_text} was reported in {pkg_count} {pkg_text}. For detailed remediation & fix ')
        lines.append('  recommendations, upgrade to a commercial license. ')

    lines.append('+==============================================================================+')

    return lines
